// ==== YSP JCE/JACC 库（对齐 jacc_client.dart 的逐行移植）====
// 运行环境：插件 set.js 沙箱（QuickJS）/ node（js_bridge 测试）。
// 依赖：宿主注入的 fn 命名空间（fn.unb64/fn.gz/fn.gunz/fn.hex/fn.randomInt）。
// 刻意不用：BigInt / DataView / TextEncoder（模板 FLOAT/DOUBLE 按原始字节透传，
// 保证往返无损；本流程所有 int 均在 ±2^53 内）。
//
// 节点表示：{ t: 类型, tag: 标签, v: 值 }
//   数值类型 → number；FLOAT/DOUBLE → Uint8Array(原始字节，编码时原样写回)；
//   字符串 → string；BYTES → [pad, n, Uint8Array]；LIST/SBEGIN → 节点数组；
//   ZERO → null。

var JCE_BYTE = 0, JCE_SHORT = 1, JCE_INT = 2, JCE_LONG = 3, JCE_FLOAT = 4,
    JCE_DOUBLE = 5, JCE_STR1 = 6, JCE_STR4 = 7, JCE_MAP = 8, JCE_LIST = 9,
    JCE_SBEGIN = 10, JCE_SEND = 11, JCE_ZERO = 12, JCE_BYTES = 13;

// --- UTF-8 编解码（纯 JS，不依赖 TextEncoder）---
function utf8Encode(s) {
  var out = [], i, c;
  for (i = 0; i < s.length; i++) {
    c = s.charCodeAt(i);
    if (c < 0x80) {
      out.push(c);
    } else if (c < 0x800) {
      out.push(0xC0 | (c >> 6), 0x80 | (c & 63));
    } else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < s.length &&
               s.charCodeAt(i + 1) >= 0xDC00 && s.charCodeAt(i + 1) <= 0xDFFF) {
      var cp = 0x10000 + ((c - 0xD800) << 10) + (s.charCodeAt(i + 1) - 0xDC00);
      out.push(0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 63),
               0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
      i++;
    } else if (c >= 0xD800 && c <= 0xDFFF) {
      out.push(0xEF, 0xBF, 0xBD); // 孤立代理 → U+FFFD
    } else {
      out.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    }
  }
  return out;
}

function utf8Decode(b) {
  var s = '', i = 0, n = b.length, c;
  while (i < n) {
    c = b[i];
    if (c < 0x80) { s += String.fromCharCode(c); i++; }
    else if (c < 0xC0) { s += '\uFFFD'; i++; }
    else if (c < 0xE0) {
      if (i + 1 >= n) { s += '\uFFFD'; break; }
      s += String.fromCharCode(((c & 31) << 6) | (b[i + 1] & 63)); i += 2;
    } else if (c < 0xF0) {
      if (i + 2 >= n) { s += '\uFFFD'; break; }
      s += String.fromCharCode(((c & 15) << 12) | ((b[i + 1] & 63) << 6) | (b[i + 2] & 63)); i += 3;
    } else {
      if (i + 3 >= n) { s += '\uFFFD'; break; }
      var cp = ((c & 7) << 18) | ((b[i + 1] & 63) << 12) | ((b[i + 2] & 63) << 6) | (b[i + 3] & 63);
      cp -= 0x10000;
      s += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
      i += 4;
    }
  }
  return s;
}

// --- 可增长字节缓冲 ---
function BB() { this.b = new Uint8Array(64); this.n = 0; }
BB.prototype.need = function (k) {
  if (this.n + k <= this.b.length) return;
  var cap = this.b.length;
  while (cap < this.n + k) cap *= 2;
  var nb = new Uint8Array(cap);
  nb.set(this.b.subarray(0, this.n));
  this.b = nb;
};
BB.prototype.u8 = function (x) { this.need(1); this.b[this.n++] = x & 0xFF; };
BB.prototype.take = function (u8) { this.need(u8.length); this.b.set(u8, this.n); this.n += u8.length; };
BB.prototype.out = function () { return this.b.subarray(0, this.n); };

// --- 大端读（有符号，对齐 Dart _unpackFromB）---
function rU16(b, i) { return (b[i] << 8) | b[i + 1]; }
function rI16(b, i) { var v = rU16(b, i); return v >= 0x8000 ? v - 0x10000 : v; }
function rI32(b, i) { return (b[i] << 24) | (b[i + 1] << 16) | (b[i + 2] << 8) | b[i + 3]; }
function rU32(b, i) { return b[i] * 0x1000000 + ((b[i + 1] << 16) | (b[i + 2] << 8) | b[i + 3]); }
function rI64(b, i) { return rI32(b, i) * 4294967296 + rU32(b, i + 4); }

// --- 大端写 ---
function wI32(bb, v) {
  bb.u8((v >>> 24) & 0xFF); bb.u8((v >>> 16) & 0xFF);
  bb.u8((v >>> 8) & 0xFF); bb.u8(v & 0xFF);
}
function wI64(bb, v) { // 0 <= v < 2^53（本流程只用非负数）
  var hi = Math.floor(v / 4294967296), lo = v - hi * 4294967296;
  wI32(bb, hi); wI32(bb, lo);
}

// --- JCE head（tag >= 15 转义：0xF0|t,tag / 0xF0|t,255,BE16）---
function rHead(b, i) {
  var h = b[i]; i++;
  var tag = (h >> 4) & 15, t = h & 15;
  if (tag === 15) {
    tag = b[i]; i++;
    if (tag === 255) { tag = rU16(b, i); i += 2; }
  }
  return { t: t, tag: tag, i: i };
}
function wHead(bb, t, tag) {
  if (tag < 15) { bb.u8((tag << 4) | t); return; }
  bb.u8(0xF0 | t);
  if (tag < 256) { bb.u8(tag); return; }
  bb.u8(255); bb.u8((tag >> 8) & 0xFF); bb.u8(tag & 0xFF);
}

// --- JCE 值读 ---
function readValue(b, i, t, tag) {
  var v = null, end = i, k, h, n;
  if (t === JCE_BYTE) { v = b[i] >= 128 ? b[i] - 256 : b[i]; end = i + 1; }
  else if (t === JCE_SHORT) { v = rI16(b, i); end = i + 2; }
  else if (t === JCE_INT) { v = rI32(b, i); end = i + 4; }
  else if (t === JCE_LONG) { v = rI64(b, i); end = i + 8; }
  else if (t === JCE_FLOAT) { v = b.subarray(i, i + 4); end = i + 4; }
  else if (t === JCE_DOUBLE) { v = b.subarray(i, i + 8); end = i + 8; }
  else if (t === JCE_STR1 || t === JCE_STR4) {
    if (t === JCE_STR1) { n = b[i]; end = i + 1; }
    else { n = rU32(b, i); end = i + 4; }
    v = utf8Decode(b.subarray(end, end + n));
    end += n;
  }
  else if (t === JCE_BYTES) {
    var pad = b[i]; i += 1;
    var cnt = readCompact(b, i); i = cnt.i;
    v = [pad, cnt.v, b.subarray(i, i + cnt.v)];
    end = i + cnt.v;
  }
  else if (t === JCE_LIST) {
    h = rHead(b, i);
    if (h.t === JCE_ZERO) { v = []; end = h.i; }
    else {
      var cn = readCompact(b, i); // 注意：用原始 i（对齐 exe/Dart）
      i = cn.i;
      v = [];
      for (k = 0; k < cn.v; k++) {
        h = rHead(b, i);
        if (h.t === JCE_ZERO) { v.push({ t: JCE_ZERO, tag: h.tag, v: null }); i = h.i; }
        else { var el = readValue(b, h.i, h.t, h.tag); v.push(el); i = el.end; }
      }
      end = i;
    }
  }
  else if (t === JCE_MAP) {
    h = rHead(b, i);
    if (h.t === JCE_ZERO) { v = []; end = h.i; }
    else {
      var mn = readCompact(b, i);
      i = mn.i;
      v = [];
      for (k = 0; k < mn.v; k++) {
        h = rHead(b, i);
        var mk = readValue(b, h.i, h.t, h.tag); i = mk.end;
        h = rHead(b, i);
        var mv = readValue(b, h.i, h.t, h.tag); i = mv.end;
        v.push({ t: JCE_MAP, tag: mk.tag, v: [mk, mv] });
      }
      end = i;
    }
  }
  else if (t === JCE_SBEGIN) {
    v = [];
    // 解析 SBEGIN：逐成员读到 SEND 为止。
    //
    // ⚠️ 不用「恒真条件」的无限循环写法：引擎有静态兜底正则（manifest.dart L1821）
    //   会把恒真条件的 while / 空条件 for 一律判为「疑似死循环」直接拒绝加载
    //   （报错「含疑似死循环…此为静态兜底，见契约 §8」）。
    //   这里改成**有界循环**：上限为剩余字节数（每个成员至少占 1 字节，
    //   所以正常数据不可能超过它），既避开静态误拦，也真正防住畸形输入
    //   导致的无限解析。
    var guard = b.length - i + 1;
    while (guard-- > 0) {
      h = rHead(b, i);
      if (h.t === JCE_SEND) { i = h.i; break; }
      if (h.t === JCE_ZERO) { v.push({ t: JCE_ZERO, tag: h.tag, v: null }); i = h.i; }
      else { var m = readValue(b, h.i, h.t, h.tag); v.push(m); i = m.end; }
    }
    end = i;
  }
  else if (t === JCE_ZERO) { v = null; end = i; }
  else { throw new Error('未知 JCE 类型 ' + t); }
  return { t: t, tag: tag, v: v, end: end };
}

// 紧凑整数读（head + 值；ZERO → 0）
function readCompact(b, i) {
  var h = rHead(b, i);
  if (h.t === JCE_ZERO) return { v: 0, i: h.i };
  var nd = readValue(b, h.i, h.t, h.tag);
  return { v: nd.v, i: nd.end };
}

// 紧凑整数写（对齐 _jceEncCompact）
function writeCompact(bb, v) {
  if (v === 0) { wHead(bb, JCE_ZERO, 0); return; }
  if (v >= -128 && v <= 127) { wHead(bb, JCE_BYTE, 0); bb.u8(v); }
  else if (v >= -32768 && v <= 32767) { wHead(bb, JCE_SHORT, 0); bb.u8((v >> 8) & 0xFF); bb.u8(v & 0xFF); }
  else if (v >= -2147483648 && v <= 2147483647) { wHead(bb, JCE_INT, 0); wI32(bb, v); }
  else { wHead(bb, JCE_LONG, 0); wI64(bb, v); }
}

// --- JCE 字段构造（对齐 _jceField L308-336）---
function jceField(val, tag) {
  if (typeof val === 'boolean') return { t: JCE_BYTE, tag: tag, v: val ? 1 : 0 };
  if (typeof val === 'number') {
    if (val === 0) return { t: JCE_ZERO, tag: tag, v: null };
    if (val >= -128 && val <= 127) return { t: JCE_BYTE, tag: tag, v: val };
    if (val >= -32768 && val <= 32767) return { t: JCE_SHORT, tag: tag, v: val };
    if (val >= -2147483648 && val <= 2147483647) return { t: JCE_INT, tag: tag, v: val };
    return { t: JCE_LONG, tag: tag, v: val };
  }
  if (typeof val === 'string') {
    return utf8Encode(val).length <= 255
      ? { t: JCE_STR1, tag: tag, v: val }
      : { t: JCE_STR4, tag: tag, v: val };
  }
  throw new Error('jceField: 不支持的类型');
}
function bytesField(u8, tag) { return { t: JCE_BYTES, tag: tag, v: [0, u8.length, u8] }; }

// --- JCE 值写 ---
function encValue(bb, nd) {
  wHead(bb, nd.t, nd.tag);
  var raw, i;
  if (nd.t === JCE_BYTE) { bb.u8(nd.v); }
  else if (nd.t === JCE_SHORT) { bb.u8((nd.v >> 8) & 0xFF); bb.u8(nd.v & 0xFF); }
  else if (nd.t === JCE_INT) { wI32(bb, nd.v); }
  else if (nd.t === JCE_LONG) { wI64(bb, nd.v); }
  else if (nd.t === JCE_FLOAT) { bb.take(nd.v); }   // 原始字节透传（无损往返）
  else if (nd.t === JCE_DOUBLE) { bb.take(nd.v); }  // 原始字节透传（无损往返）
  else if (nd.t === JCE_STR1) {
    raw = utf8Encode(nd.v);
    bb.u8(raw.length);
    for (i = 0; i < raw.length; i++) bb.u8(raw[i]);
  }
  else if (nd.t === JCE_STR4) {
    raw = utf8Encode(nd.v);
    wI32(bb, raw.length);
    for (i = 0; i < raw.length; i++) bb.u8(raw[i]);
  }
  else if (nd.t === JCE_BYTES) { bb.u8(nd.v[0]); writeCompact(bb, nd.v[1]); bb.take(nd.v[2]); }
  else if (nd.t === JCE_LIST) {
    writeCompact(bb, nd.v.length);
    for (i = 0; i < nd.v.length; i++) encValue(bb, nd.v[i]);
  }
  else if (nd.t === JCE_MAP) {
    writeCompact(bb, nd.v.length);
    for (i = 0; i < nd.v.length; i++) { encValue(bb, nd.v[i].v[0]); encValue(bb, nd.v[i].v[1]); }
  }
  else if (nd.t === JCE_SBEGIN) {
    for (i = 0; i < nd.v.length; i++) encValue(bb, nd.v[i]);
    wHead(bb, JCE_SEND, 0);
  }
  else if (nd.t === JCE_ZERO) { /* 无载荷 */ }
  else { throw new Error('encValue: 不支持的类型 ' + nd.t); }
}
function encStruct(nodes) {
  var bb = new BB();
  for (var i = 0; i < nodes.length; i++) encValue(bb, nodes[i]);
  return bb.out();
}

// --- 顶层 struct 解析（遇 SEND 停）---
function parseStruct(b) {
  var out = [], i = 0, n = b.length, h;
  while (i < n) {
    h = rHead(b, i);
    if (h.t === JCE_SEND) break;
    if (h.t === JCE_ZERO) { out.push({ t: JCE_ZERO, tag: h.tag, v: null }); i = h.i; }
    else { var m = readValue(b, h.i, h.t, h.tag); out.push(m); i = m.end; }
  }
  return out;
}

// --- JACC 封包（对齐 _jaccUnwrapJce/_jaccRewrap/_jaccBuildBody）---
function jaccUnwrapJce(body) {
  var gz = body.subarray(89, body.length - 1);
  var inner = fn.gunz(gz);
  if (inner.length <= 17) return inner;
  return inner.subarray(16, inner.length - 1);
}

function jaccRewrap(tpl, cmd, jce, rqid) {
  // inner = b'&' + BE32(len(jce)+17) + 0x01 + 10 零 + jce + b'('
  var ilen = jce.length + 17;
  var inner = new Uint8Array(ilen);
  inner[0] = 0x26;
  inner[1] = (ilen >>> 24) & 0xFF; inner[2] = (ilen >>> 16) & 0xFF;
  inner[3] = (ilen >>> 8) & 0xFF; inner[4] = ilen & 0xFF;
  inner[5] = 0x01;
  inner.set(jce, 16);
  inner[ilen - 1] = 0x28;
  var gz = fn.gz(inner);
  if (gz.length >= 10) gz[9] = 0; // OS 字节置 0（对齐 _jaccGzip L420-426）
  var out = new Uint8Array(89 + gz.length + 1);
  out[0] = 0x13;
  out.set(tpl.subarray(5, 9), 5);     // hdr2 + magic2（模板原样）
  out[9] = (cmd >>> 8) & 0xFF; out[10] = cmd & 0xFF;
  out.set(tpl.subarray(11, 13), 11);  // z0（模板原样）
  var hi = Math.floor(rqid / 4294967296), lo = rqid - hi * 4294967296;
  out[13] = (hi >>> 24) & 0xFF; out[14] = (hi >>> 16) & 0xFF; out[15] = (hi >>> 8) & 0xFF; out[16] = hi & 0xFF;
  out[17] = (lo >>> 24) & 0xFF; out[18] = (lo >>> 16) & 0xFF; out[19] = (lo >>> 8) & 0xFF; out[20] = lo & 0xFF;
  out.set(tpl.subarray(21, 85), 21);  // c531..s83（模板原样 64 字节）
  out[85] = (ilen >>> 24) & 0xFF; out[86] = (ilen >>> 16) & 0xFF; out[87] = (ilen >>> 8) & 0xFF; out[88] = ilen & 0xFF;
  out.set(gz, 89);
  out[out.length - 1] = 0x03;
  out[1] = (out.length >>> 24) & 0xFF; out[2] = (out.length >>> 16) & 0xFF;
  out[3] = (out.length >>> 8) & 0xFF; out[4] = out.length & 0xFF;
  return out;
}

function jaccBuildBody(tpl, guid, cmd, bodyJce, rqid) {
  var jceTpl = jaccUnwrapJce(tpl);
  var members = parseStruct(jceTpl);
  var head = members[0];
  var me = {}, i, replaced = false;
  for (i = 0; i < head.v.length; i++) me[head.v[i].tag] = head.v[i];
  // setInt：原地改值并按范围重定型（Dart L525-534）
  me[0].v = rqid;
  me[0].t = (rqid >= -128 && rqid <= 127) ? JCE_BYTE
    : ((rqid >= -32768 && rqid <= 32767) ? JCE_SHORT : JCE_INT);
  me[1].v = cmd;
  me[1].t = (cmd >= -128 && cmd <= 127) ? JCE_BYTE
    : ((cmd >= -32768 && cmd <= 32767) ? JCE_SHORT : JCE_INT);
  me[4].v = guid;
  // LoginToken（tag 5）：本流程无 session → ZERO（Dart L556-558）
  var loginTok = { t: JCE_ZERO, tag: 5, v: null };
  for (i = 0; i < head.v.length; i++) {
    if (head.v[i].tag === 5) { head.v[i] = loginTok; replaced = true; break; }
  }
  if (!replaced) head.v.push(loginTok);
  members[1] = bytesField(bodyJce, 1);
  var bb = new BB();
  for (i = 0; i < members.length; i++) encValue(bb, members[i]);
  return jaccRewrap(tpl, cmd, bb.out(), rqid);
}

// --- App 认证体（对齐 _jceBuildAppAuthBody L665-698）---
function buildAppAuthBody(etype, openid, guid, access, refresh, code) {
  var oauth = { t: JCE_SBEGIN, tag: 1, v: [
    jceField('', 0), jceField(openid, 1), jceField(access, 2),
    jceField(refresh, 3), jceField(code, 4),
    { t: JCE_ZERO, tag: 5, v: null }
  ] };
  var token = { t: JCE_SBEGIN, tag: 0, v: [jceField(etype, 0), oauth] };
  var dev = { t: JCE_SBEGIN, tag: 1, v: [
    jceField(8, 0), jceField('', 1), jceField(guid, 2),
    jceField('e62d0096c4cd523e', 3), jceField('Xiaomi,31,12', 4)
  ] };
  return encStruct([{ t: JCE_LIST, tag: 0, v: [token] }, dev]);
}

// --- App 认证体解析（对齐 _jceParseAuthBody L704-776）---
function pick(g, tag, def) {
  var n = g[tag];
  if (!n || n.t === JCE_ZERO) return def;
  return n.v;
}

function parseAuthBody(raw) {
  var out = { ret: 0, msg: '', openid: '', access_token: '', refresh_token: '',
              access_ttl: 0, vuserid: '', vusession: '', session_ttl: 0 };
  var sub = parseStruct(raw);
  var i, m;
  for (i = 0; i < sub.length; i++) {
    m = sub[i];
    if (m.tag === 0) { out.ret = (m.t === JCE_ZERO) ? 0 : m.v; break; }
  }
  for (i = 0; i < sub.length; i++) {
    m = sub[i];
    if (m.tag === 1) { out.msg = (m.t === JCE_ZERO) ? '' : String(m.v); break; }
  }
  for (i = 0; i < sub.length; i++) {
    m = sub[i];
    if (m.tag === 2 && m.t === JCE_SBEGIN) {
      for (var j = 0; j < m.v.length; j++) {
        var c = m.v[j];
        if (c.tag === 1 && c.t === JCE_SBEGIN) {
          var g = {};
          for (var x = 0; x < c.v.length; x++) g[c.v[x].tag] = c.v[x];
          out.openid = pick(g, 1, out.openid);
          out.access_token = pick(g, 2, out.access_token);
          out.refresh_token = pick(g, 3, out.refresh_token);
          out.access_ttl = pick(g, 5, out.access_ttl);
          break;
        }
      }
      break;
    }
  }
  for (i = 0; i < sub.length; i++) {
    m = sub[i];
    if (m.tag === 3 && m.t === JCE_SBEGIN) {
      var g2 = {};
      for (var y = 0; y < m.v.length; y++) g2[m.v[y].tag] = m.v[y];
      out.vuserid = String(pick(g2, 0, out.vuserid));
      out.vusession = pick(g2, 1, out.vusession);
      out.session_ttl = pick(g2, 2, out.session_ttl);
      break;
    }
  }
  return out;
}
// ==== 构建阶段（buildSend / buildLogin / buildRenew 共用）====
// inputs（模板渲染后的字符串）：
//   tplB64  模板 base64（vars.jaccTplB64）
//   mode    'send' | 'login' | 'renew'
//   guid    运行时 guid（vars.guid）
//   phone   手机号（send/login；renew 时可缺省）
//   smsCode 短信验证码（login）
//   openid / access / refresh（renew）
// 返回：{ packet: hex, rqid: string }（rqid 每次调用新生成，供 request-id 头）
var __tpl = fn.unb64(tplB64);
var __cmd = mode === 'send' ? 24680 : (mode === 'login' ? 59986 : 59987);
var __phone = (typeof phone === 'string')
  ? (phone.charAt(0) === '+' ? phone : '+86' + phone)
  : '';
var __body;
if (mode === 'send') {
  __body = encStruct([
    jceField('1400227916', 0),
    jceField(__phone, 1),
    jceField('', 2),
    jceField('ONE', 3),
    jceField('86', 6)
  ]);
} else if (mode === 'login') {
  __body = buildAppAuthBody(104, __phone, guid, '', '', smsCode);
} else {
  __body = buildAppAuthBody(104, openid, guid, access, refresh, '');
